import { z } from 'zod';
import { requireUser } from '@/lib/auth';
import { json, readJson, route, HttpError } from '@/lib/http';
import { audit } from '@/lib/audit';
import { hasActiveAccess } from '@/repos/careTeam';
import { getPractitioner } from '@/repos/practitioners';
import { createAppointment, listForPatient } from '@/repos/appointments';

const BookBody = z.object({
  practitionerId: z.string().min(1),
  startsAt: z.string().datetime(),
  endsAt: z.string().datetime(),
  visitReason: z.string().max(500).nullable().optional(),
});

/** The signed-in patient's appointments. */
export const GET = route(async (req) => {
  const user = await requireUser(req);
  if (user.role !== 'patient' || !user.patientId) throw new HttpError(403, 'forbidden');
  const rows = await listForPatient(user.patientId);
  return json({
    appointments: rows.map((a) => ({
      id: a.id,
      practitionerId: a.practitioner_id,
      startsAt: a.starts_at,
      endsAt: a.ends_at,
      status: a.status,
      visitReason: a.visit_reason,
    })),
  });
});

/** A patient books an appointment with a practitioner of their care team. */
export const POST = route(async (req) => {
  const user = await requireUser(req);
  if (user.role !== 'patient' || !user.patientId) throw new HttpError(403, 'forbidden');
  const input = BookBody.parse(await readJson(req));

  const practitioner = await getPractitioner(input.practitionerId);
  if (!practitioner || practitioner.org_id !== user.orgId) throw new HttpError(404, 'not_found');
  if (!(await hasActiveAccess(practitioner.id, user.patientId))) throw new HttpError(403, 'forbidden');

  const startsAt = new Date(input.startsAt);
  const endsAt = new Date(input.endsAt);
  if (!(endsAt > startsAt)) throw new HttpError(400, 'invalid_time_range');

  const id = await createAppointment({
    orgId: user.orgId,
    patientId: user.patientId,
    practitionerId: practitioner.id,
    startsAt,
    endsAt,
    visitReason: input.visitReason ?? null,
    createdByUserId: user.id,
  });
  await audit(user, 'appointment.book', 'appointment', id);
  return json({ id }, 201);
});
import nodemailer from 'nodemailer';
import { env } from './env';

export interface Mail {
  to: string;
  subject: string;
  text: string;
}

/** In-memory outbox used when MAIL_TRANSPORT=memory (tests). */
export const mailOutbox: Mail[] = [];

let transporter: nodemailer.Transporter | undefined;

function getTransporter(): nodemailer.Transporter {
  if (!transporter) {
    transporter = nodemailer.createTransport({
      host: env.smtpHost,
      port: env.smtpPort,
      secure: false,
      ignoreTLS: true,
    });
  }
  return transporter;
}

export async function sendMail(mail: Mail): Promise<void> {
  if (env.mailTransport === 'memory') {
    mailOutbox.push(mail);
    return;
  }
  await getTransporter().sendMail({ from: env.mailFrom, to: mail.to, subject: mail.subject, text: mail.text });
}
import { appendFileSync, mkdirSync } from 'node:fs';
import path from 'node:path';
import { env } from './env';

type Level = 'debug' | 'info' | 'warn' | 'error';
type Fields = Record<string, unknown>;

function serialize(value: unknown): unknown {
  if (value instanceof Error) {
    // Keep enumerable props (driver error codes etc.) alongside name and message.
    return { ...(value as unknown as Record<string, unknown>), name: value.name, message: value.message };
  }
  return value;
}

function write(level: Level, msg: string, fields: Fields = {}): void {
  const out: Fields = { ts: new Date().toISOString(), level, msg };
  for (const [k, v] of Object.entries(fields)) out[k] = serialize(v);
  const line = JSON.stringify(out);
  if (level === 'error' || level === 'warn') process.stderr.write(line + '\n');
  else process.stdout.write(line + '\n');
  const file = env.logFile;
  if (file) {
    mkdirSync(path.dirname(file), { recursive: true });
    appendFileSync(file, line + '\n');
  }
}

/**
 * Structured JSON logger. One line per event.
 * Usage: logger.info('message sent', { messageId, senderId }).
 */
export const logger = {
  debug: (msg: string, fields?: Fields) => write('debug', msg, fields),
  info: (msg: string, fields?: Fields) => write('info', msg, fields),
  warn: (msg: string, fields?: Fields) => write('warn', msg, fields),
  error: (msg: string, fields?: Fields) => write('error', msg, fields),
};
import { execute, queryOne } from '@/lib/db';

export async function hasActiveAccess(practitionerId: string, patientId: string): Promise<boolean> {
  const row = await queryOne(
    'SELECT 1 AS ok FROM care_team WHERE practitioner_id = ? AND patient_id = ? AND active = 1',
    [practitionerId, patientId],
  );
  return row !== null;
}

/** Removes a practitioner's access to a patient. Returns false if there was no active access. */
export async function revokeAccess(practitionerId: string, patientId: string): Promise<boolean> {
  const res = await execute(
    'UPDATE care_team SET active = 0, revoked_at = UTC_TIMESTAMP(3) WHERE practitioner_id = ? AND patient_id = ? AND active = 1',
    [practitionerId, patientId],
  );
  return res.affectedRows > 0;
}
import { queryOne } from '@/lib/db';
import type { Role } from '@/lib/auth';

export interface UserRow {
  id: string;
  org_id: string;
  role: Role;
  email: string;
  display_name: string;
}

export async function getUser(userId: string): Promise<UserRow | null> {
  return queryOne<UserRow>('SELECT id, org_id, role, email, display_name FROM users WHERE id = ?', [userId]);
}
import { describe, expect, it } from 'vitest';
import { GET } from '@/app/api/appointments/route';
import { call, TOKENS } from './helpers';

describe('GET /api/appointments', () => {
  it('lists only the signed-in patient appointments', async () => {
    const res = await call(GET, { token: TOKENS.ava });
    expect(res.status).toBe(200);
    const ids = res.json.appointments.map((a: { id: string }) => a.id);
    expect(ids).toEqual(expect.arrayContaining(['apt_001', 'apt_004']));
    expect(ids).not.toContain('apt_002');
  });

  it('is for patients only', async () => {
    const res = await call(GET, { token: TOKENS.rosa });
    expect(res.status).toBe(403);
  });
});
